package predict

import (
	"bufio"
	"encoding/json"
	"os"
	"testing"
)

// TestPiWrapMatchesPiTui compares piWrap with vectors generated by pi-tui's
// own wordWrapLine (testdata/pitui-wrap.jsonl, from Pi 1.5.2): words,
// repeated and trailing spaces, force-broken words, CJK breaks between any
// two characters, full-width punctuation and mixed CJK and ASCII.
func TestPiWrapMatchesPiTui(t *testing.T) {
	f, err := os.Open("testdata/pitui-wrap.jsonl")
	if err != nil {
		t.Fatal(err)
	}
	defer f.Close()
	scanner := bufio.NewScanner(f)
	n := 0
	for scanner.Scan() {
		var v struct {
			Line   string   `json:"line"`
			W      int      `json:"w"`
			Chunks []string `json:"chunks"`
		}
		if err := json.Unmarshal(scanner.Bytes(), &v); err != nil {
			t.Fatal(err)
		}
		n++
		elems := TextElems(v.Line)
		var got []string
		for _, r := range piWrap(elems, v.W) {
			got = append(got, State{Elems: elems[r.Start:r.End]}.Text())
		}
		if len(got) != len(v.Chunks) {
			t.Errorf("%q at %d: got %q, pi-tui %q", v.Line, v.W, got, v.Chunks)
			continue
		}
		for i := range got {
			if got[i] != v.Chunks[i] {
				t.Errorf("%q at %d: got %q, pi-tui %q", v.Line, v.W, got, v.Chunks)
				break
			}
		}
	}
	if n < 10 {
		t.Fatalf("only %d vectors", n)
	}
}
